pragma solidity ^0.8.0;

// Libraries
import { InvalidExitedValue } from "src/cannon/libraries/CannonErrors.sol";

library MIPS64State {
    struct CpuScalars {
        uint64 pc;
        uint64 nextPC;
        uint64 lo;
