// SPDX-License-Identifier: MIT
pragma solidity >=0.8.25;

// Interfaces
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { ISemver } from "interfaces/universal/ISemver.sol";

// Libraries
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

// Inheritance
import { Ownable } from "@openzeppelin/contracts-v5/access/Ownable.sol";
import { Ownable2Step } from "@openzeppelin/contracts-v5/access/Ownable2Step.sol";

/// @title PolicyEngineStakingMapping
/// @notice Holds the `peData` mapping at storage slot 0 so that `op-rbuilder` can read
///         effective-stake data at a known, stable location. Inherited first by
///         `PolicyEngineStaking` to guarantee the slot assignment.
contract PolicyEngineStakingMapping {
    /// @notice Policy Engine data per account. Packed in one slot for PE reads.
    /// @custom:field effectiveStake The exact stake amount used for ordering.
    /// @custom:field lastUpdate The timestamp of the latest change on their effective stake.
    struct PEData {
        uint128 effectiveStake;
        uint128 lastUpdate;
    }

    /// @notice Base storage slot for PE data mapping. Policy Engine reads from
    ///         keccak256(abi.encode(account, PE_DATA_SLOT)).
    bytes32 public constant PE_DATA_SLOT = 0;

    /// @notice Slot 0: PE data mapping.
    mapping(address account => PEData) public peData;
}

/// @title PolicyEngineStaking
/// @notice Periphery contract for stake-based transaction ordering in op-rbuilder. Users stake governance tokens
///         and optionally link to a beneficiary who receives ordering power. Supports partial unstake.
///         Invariant: every staked token has a beneficiary (self or linked). No receivedStake tracking or unlink().
contract PolicyEngineStaking is PolicyEngineStakingMapping, Ownable2Step, ISemver {
    using SafeERC20 for IERC20;

    /// @notice Staking stakingData per account.
    /// @custom:field stakedAmount The amount of OP tokens staked by the account.
    /// @custom:field beneficiary The address to which the account's stake is attributed.
    struct StakedData {
        uint128 stakedAmount;
        address beneficiary;
    }

    /// @notice Semantic version.
    /// @custom:semver 1.0.0
    string public constant version = "1.0.0";

    /// @notice The ERC20 token used for staking.
    // nosemgrep: sol-safety-no-immutable-variables
    IERC20 internal immutable STAKING_TOKEN;

    /// @notice Allowlist: beneficiary => staker => allowed.
    mapping(address beneficiary => mapping(address staker => bool allowed)) public allowlist;

    /// @notice Staking stakingData mapping.
    mapping(address account => StakedData) public stakingData;

    /// @notice Paused state.
    bool public paused;

    /// @notice Emitted when a user stakes OP tokens.
    /// @param account The address that staked tokens.
    /// @param amount  The amount of tokens staked.
    event Staked(address indexed account, uint128 amount);

    /// @notice Emitted when a user unstakes OP tokens.
    /// @param account The address that unstaked tokens.
    /// @param amount  The amount of tokens unstaked.
    event Unstaked(address indexed account, uint128 amount);

    /// @notice Emitted when a staker sets their beneficiary.
    /// @param staker      The address setting their beneficiary.
    /// @param beneficiary The address receiving ordering power.
    event BeneficiarySet(address indexed staker, address indexed beneficiary);

    /// @notice Emitted when a staker's beneficiary is removed (on change or full unstake).
    /// @param staker              The address whose beneficiary was removed.
    /// @param previousBeneficiary The previous beneficiary.
    event BeneficiaryRemoved(address indexed staker, address indexed previousBeneficiary);

    /// @notice Emitted when effective stake changes for an account.
    /// @param account           The account whose effective stake changed.
    /// @param newEffectiveStake The new effective stake value.
    event EffectiveStakeChanged(address indexed account, uint256 newEffectiveStake);

    /// @notice Emitted when a beneficiary updates their allowlist.
    /// @param beneficiary The address controlling the allowlist.
    /// @param staker      The staker whose permission changed.
    /// @param allowed     The new permission state.
    event BeneficiaryAllowlistUpdated(address indexed beneficiary, address indexed staker, bool allowed);

    /// @notice Emitted when staking is paused.
    event Paused();

    /// @notice Emitted when the staking is unpaused.
    event Unpaused();

    /// @notice Thrown when the staking is paused.
    error PolicyEngineStaking_Paused();

    /// @notice Thrown when the amount is zero.
    error PolicyEngineStaking_ZeroAmount();

    /// @notice Thrown when the beneficiary address is zero.
    error PolicyEngineStaking_ZeroBeneficiary();

    /// @notice Thrown when the staker is not allowed to set the beneficiary.
    error PolicyEngineStaking_NotAllowedToSetBeneficiary();

    /// @notice Thrown when trying to operate with no stake.
    error PolicyEngineStaking_NoStake();

    /// @notice Thrown when trying to unstake more than the staked amount.
    error PolicyEngineStaking_InsufficientStake();

    /// @notice Thrown when a zero address is provided where it is not allowed.
    error PolicyEngineStaking_ZeroAddress();

    /// @notice Thrown when trying to change beneficiary to the current beneficiary.
    error PolicyEngineStaking_SameBeneficiary();

    /// @notice Thrown when trying to allowlist/disallow yourself.
    error PolicyEngineStaking_SelfAllowlist();

    /// @notice Constructs the PolicyEngineStaking contract.
    /// @param _ownerAddr The address that can pause and unpause staking.
    /// @param _token The ERC20 token used for staking.
    constructor(address _ownerAddr, address _token) Ownable(_ownerAddr) {
        if (_token == address(0)) revert PolicyEngineStaking_ZeroAddress();
        STAKING_TOKEN = IERC20(_token);
    }

    /// @notice Modifier that reverts when the staking is paused.
    modifier whenNotPaused() {
        if (paused) revert PolicyEngineStaking_Paused();
        _;
    }

    /// @notice Returns the staking token address.
    ///
    /// @return The ERC20 token used for staking.
    function stakingToken() external view returns (IERC20) {
        return STAKING_TOKEN;
    }

    /// @notice Pauses the contract. Stake is disabled while paused.
    function pause() external onlyOwner {
        paused = true;
        emit Paused();
    }

    /// @notice Unpauses the contract.
    function unpause() external onlyOwner {
        paused = false;
        emit Unpaused();
    }

    /// @notice Stakes tokens and sets beneficiary atomically.
    ///         This is the entry point for staking. Handles first-time staking,
    ///         adding to same beneficiary, and changing to a new beneficiary.
    /// @param _amount      The amount of tokens to stake.
    /// @param _beneficiary Address that receives ordering power from this stake.
    ///                     Use msg.sender for self-attribution.
    function stake(uint128 _amount, address _beneficiary) external whenNotPaused {
        if (_amount == 0) revert PolicyEngineStaking_ZeroAmount();
        if (_beneficiary == address(0)) revert PolicyEngineStaking_ZeroBeneficiary();
        if (_beneficiary != msg.sender && !allowlist[_beneficiary][msg.sender]) {
            revert PolicyEngineStaking_NotAllowedToSetBeneficiary();
        }

        StakedData storage stakedData = stakingData[msg.sender];
        address currentBeneficiary = stakedData.beneficiary;

        // Remove previous beneficiary
        if (currentBeneficiary != _beneficiary) {
            if (currentBeneficiary != address(0)) {
                _decreasePeData(currentBeneficiary, stakedData.stakedAmount);
                emit BeneficiaryRemoved(msg.sender, currentBeneficiary);
            }
            stakedData.beneficiary = _beneficiary;
            emit BeneficiarySet(msg.sender, _beneficiary);
        }

        stakedData.stakedAmount += _amount;

        // If the beneficiary hasn't changed, peDelta is just the new amount staked.
        // If the beneficiary changed, peDelta is the full total stake amount (previous + new stake),
        // since the new beneficiary now receives ordering power for the entire position.
        uint128 peDelta = currentBeneficiary == _beneficiary ? _amount : stakedData.stakedAmount;
        _increasePeData(_beneficiary, peDelta);

        STAKING_TOKEN.safeTransferFrom(msg.sender, address(this), uint256(_amount));

        emit Staked(msg.sender, _amount);
    }

    /// @notice Changes the beneficiary for existing stake. Reverts if already set
    ///         to the same beneficiary.
    /// @param _beneficiary New beneficiary address.
    function changeBeneficiary(address _beneficiary) external whenNotPaused {
        if (_beneficiary == address(0)) revert PolicyEngineStaking_ZeroBeneficiary();
        if (_beneficiary != msg.sender && !allowlist[_beneficiary][msg.sender]) {
            revert PolicyEngineStaking_NotAllowedToSetBeneficiary();
        }

        StakedData storage stakedData = stakingData[msg.sender];
        if (stakedData.stakedAmount == 0) revert PolicyEngineStaking_NoStake();

        address currentBeneficiary = stakedData.beneficiary;
        if (currentBeneficiary == _beneficiary) revert PolicyEngineStaking_SameBeneficiary();

        // Move existing stake from old beneficiary to new
        _decreasePeData(currentBeneficiary, stakedData.stakedAmount);
        emit BeneficiaryRemoved(msg.sender, currentBeneficiary);

        stakedData.beneficiary = _beneficiary;
        _increasePeData(_beneficiary, stakedData.stakedAmount);

        emit BeneficiarySet(msg.sender, _beneficiary);
    }

    /// @notice Unstakes OP tokens. Supports partial and full unstake.
    ///         On full unstake, the beneficiary is automatically cleared.
    /// @param _amount The amount of OP tokens to unstake.
    function unstake(uint128 _amount) external {
        if (_amount == 0) revert PolicyEngineStaking_ZeroAmount();

        StakedData storage stakedData = stakingData[msg.sender];
        if (stakedData.stakedAmount < _amount) revert PolicyEngineStaking_InsufficientStake();

        address beneficiary = stakedData.beneficiary;
        _decreasePeData(beneficiary, _amount);
        stakedData.stakedAmount -= _amount;

        // Auto-clear beneficiary on full unstake
        if (stakedData.stakedAmount == 0) {
            stakedData.beneficiary = address(0);
            emit BeneficiaryRemoved(msg.sender, beneficiary);
        }

        STAKING_TOKEN.safeTransfer(msg.sender, uint256(_amount));

        emit Unstaked(msg.sender, _amount);
    }

    /// @notice Sets whether a staker can set the caller as beneficiary. When disallowing,
    ///         if the staker's current beneficiary is the caller, their stake attribution is
    ///         moved back to the staker (beneficiary reset to self).
    /// @dev    This function is intentionally NOT gated by `whenNotPaused`. Allowlist
    ///         mutations remain available during pause so that beneficiaries can revoke
    ///         stakers at any time. Note that disallowing a staker who is currently
    ///         delegated to the caller will move effective stake attribution back to the
    ///         staker, changing ordering-power state even while the contract is paused.
    /// @dev    Trust assumption: stakers who delegate to a beneficiary implicitly trust
    ///         that the beneficiary will not remove them from the allowlist at a
    ///         disadvantageous time. Removal triggers `_increasePeData` on the staker,
    ///         which resets their `lastUpdate` and thus their accumulated staking weight.
    /// @param _staker The staker to allow or deny.
    /// @param _allowed The allowed state.
    function setAllowedStaker(address _staker, bool _allowed) public {
        if (_staker == msg.sender) revert PolicyEngineStaking_SelfAllowlist();

        allowlist[msg.sender][_staker] = _allowed;
        emit BeneficiaryAllowlistUpdated(msg.sender, _staker, _allowed);

        if (!_allowed) {
            StakedData storage stakedData = stakingData[_staker];
            if (stakedData.beneficiary == msg.sender) {
                _decreasePeData(msg.sender, stakedData.stakedAmount);
                emit BeneficiaryRemoved(_staker, msg.sender);

                stakedData.beneficiary = _staker;
                _increasePeData(_staker, stakedData.stakedAmount);
                emit BeneficiarySet(_staker, _staker);
            }
        }
    }

    /// @notice Batch sets allowlist for multiple stakers.
    /// @param _stakers The stakers to allow or deny.
    /// @param _allowed The allowed state.
    function setAllowedStakers(address[] calldata _stakers, bool _allowed) external {
        uint256 stakersLength = _stakers.length;

        for (uint256 i; i < stakersLength; ++i) {
            setAllowedStaker(_stakers[i], _allowed);
        }
    }

    /// @notice Increases effective stake for an account and updates timestamp.
    /// @param _account The account address.
    /// @param _amount  The amount to add.
    function _increasePeData(address _account, uint128 _amount) internal {
        PEData storage pe = peData[_account];
        pe.effectiveStake += _amount;
        pe.lastUpdate = uint128(block.timestamp);
        emit EffectiveStakeChanged(_account, pe.effectiveStake);
    }

    /// @notice Decreases effective stake for an account. Only resets `lastUpdate` when
    ///         the effective stake reaches zero to avoid stale timestamps; otherwise the
    ///         existing timestamp is preserved so remaining stake keeps its staking weight.
    ///
    /// @param _account The account address.
    /// @param _amount  The amount to subtract.
    function _decreasePeData(address _account, uint128 _amount) internal {
        PEData storage pe = peData[_account];
        pe.effectiveStake -= _amount;
        if (pe.effectiveStake == 0) {
            pe.lastUpdate = uint128(block.timestamp);
        }
        emit EffectiveStakeChanged(_account, pe.effectiveStake);
    }
}

src/safe/DeputyPauseModule.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.25;

// Safe
import { Safe } from "safe-contracts/Safe.sol";
import { Enum } from "safe-contracts/common/Enum.sol";

// Contracts
import { EIP712 } from "@openzeppelin/contracts-v5/utils/cryptography/EIP712.sol";

// Libraries
import { ECDSA } from "@openzeppelin/contracts-v5/utils/cryptography/ECDSA.sol";

// Interfaces
import { ISemver } from "interfaces/universal/ISemver.sol";
import { ISuperchainConfig } from "interfaces/L1/ISuperchainConfig.sol";

/// @title DeputyPauseModule
/// @notice Safe Module designed to be installed into the Guardian Safe which allows a specific
///         deputy address to act as the Guardian Safe for the sake of triggering a pause within
///         the SuperchainConfig contract.
contract DeputyPauseModule is ISemver, EIP712 {
    /// @notice Error message for deputy being invalid.
    error DeputyPauseModule_InvalidDeputy();

    /// @notice Error message for unauthorized calls.
    error DeputyPauseModule_Unauthorized();

    /// @notice Error message for nonce reuse.
    error DeputyPauseModule_NonceAlreadyUsed();

    /// @notice Error message for failed transaction execution.
    error DeputyPauseModule_ExecutionFailed(string);

    /// @notice Error message for the SuperchainConfig not being paused.
    error DeputyPauseModule_SuperchainNotPaused();

    /// @notice Error message for the call not being from the Foundation Safe.
    error DeputyPauseModule_NotFromSafe();

    /// @notice Struct for the Pause action.
    /// @custom:field nonce Signature nonce.
    /// @custom:field identifier Identifier to pause.
    struct PauseMessage {
        bytes32 nonce;
        address identifier;
    }

    /// @notice Struct for the DeputyAuth action.
    /// @custom:field deputy Address of the deputy account.
    struct DeputyAuthMessage {
        address deputy;
    }

    /// @notice Event emitted when the deputy address is set.
    event DeputySet(address indexed deputy);

    /// @notice Event emitted when the pause is triggered.
    event PauseTriggered(address indexed deputy, bytes32 nonce, address identifier);

    /// @notice Guardian Safe.
    Safe internal immutable GUARDIAN_SAFE;

    /// @notice Foundation Safe.
    Safe internal immutable FOUNDATION_SAFE;

    /// @notice SuperchainConfig contract.
    ISuperchainConfig internal immutable SUPERCHAIN_CONFIG;

    /// @notice Typehash for the Pause action.
    bytes32 internal constant PAUSE_MESSAGE_TYPEHASH = keccak256("PauseMessage(bytes32 nonce,address identifier)");

    /// @notice Typehash for the DeputyAuth message.
    bytes32 internal constant DEPUTY_AUTH_MESSAGE_TYPEHASH = keccak256("DeputyAuthMessage(address deputy)");

    /// @notice Address of the Deputy account.
    address public deputy;

    /// @notice Used nonces.
    mapping(bytes32 => bool) public usedNonces;

    /// @notice Semantic version.
    /// @custom:semver 3.0.0
    string public constant version = "3.0.0";

    /// @param _guardianSafe Address of the Guardian Safe.
    /// @param _foundationSafe Address of the Foundation Safe.
    /// @param _superchainConfig Address of the SuperchainConfig contract.
    /// @param _deputy Address of the deputy account.
    /// @param _deputySignature Signature from the deputy verifying that the account is an EOA.
    constructor(
        Safe _guardianSafe,
        Safe _foundationSafe,
        ISuperchainConfig _superchainConfig,
        address _deputy,
        bytes memory _deputySignature
    )
        EIP712("DeputyPauseModule", "1")
    {
        _setDeputy(_deputy, _deputySignature);
        GUARDIAN_SAFE = _guardianSafe;
        FOUNDATION_SAFE = _foundationSafe;
        SUPERCHAIN_CONFIG = _superchainConfig;
    }

    /// @notice Getter function for the Guardian Safe address.
    /// @return guardianSafe_ Guardian Safe address.
    function guardianSafe() public view returns (Safe guardianSafe_) {
        guardianSafe_ = GUARDIAN_SAFE;
    }

    /// @notice Getter function for the Foundation Safe address.
    /// @return foundationSafe_ Foundation Safe address.
    function foundationSafe() public view returns (Safe foundationSafe_) {
        foundationSafe_ = FOUNDATION_SAFE;
    }

    /// @notice Getter function for the SuperchainConfig address.
    /// @return superchainConfig_ SuperchainConfig address.
    function superchainConfig() public view returns (ISuperchainConfig superchainConfig_) {
        superchainConfig_ = SUPERCHAIN_CONFIG;
    }

    /// @notice Getter function for the Pause message typehash.
    /// @return pauseMessageTypehash_ Pause message typehash.
    function pauseMessageTypehash() public pure returns (bytes32 pauseMessageTypehash_) {
        pauseMessageTypehash_ = PAUSE_MESSAGE_TYPEHASH;
    }

    /// @notice Getter function for the DeputyAuth message typehash.
    /// @return deputyAuthMessageTypehash_ DeputyAuth message typehash.
    function deputyAuthMessageTypehash() public pure returns (bytes32 deputyAuthMessageTypehash_) {
        deputyAuthMessageTypehash_ = DEPUTY_AUTH_MESSAGE_TYPEHASH;
    }

    /// @notice Sets the deputy address.
    /// @param _deputy Deputy address.
    /// @param _deputySignature Deputy signature.
    function setDeputy(address _deputy, bytes memory _deputySignature) external {
        // Can only be called by the Foundation Safe itself.
        if (msg.sender != address(FOUNDATION_SAFE)) {
            revert DeputyPauseModule_NotFromSafe();
        }

        // Set the deputy address.
        _setDeputy(_deputy, _deputySignature);
    }

    /// @notice Calls the Guardian Safe's `execTransactionFromModuleReturnData()` function with
    ///         the arguments necessary to call `pause()` on the SuperchainConfig.
    ///         Front-running this function is completely safe, it'll pause either way.
    /// @param _nonce Signature nonce.
    /// @param _identifier The identifier to pause in the SuperchainConfig.
    /// @param _signature ECDSA signature.
    function pause(bytes32 _nonce, address _identifier, bytes memory _signature) external {
        // Verify the signature.
        bytes32 digest = _hashTypedDataV4(keccak256(abi.encode(PAUSE_MESSAGE_TYPEHASH, _nonce, _identifier)));
        if (ECDSA.recover(digest, _signature) != deputy) {
            revert DeputyPauseModule_Unauthorized();
        }

        // Make sure the nonce hasn't been used yet.
        if (usedNonces[_nonce]) {
            revert DeputyPauseModule_NonceAlreadyUsed();
        }

        // Mark the nonce as used.
        usedNonces[_nonce] = true;

        // Attempt to trigger the call.
        (bool success, bytes memory returnData) = GUARDIAN_SAFE.execTransactionFromModuleReturnData(
            address(SUPERCHAIN_CONFIG), 0, abi.encodeCall(ISuperchainConfig.pause, (_identifier)), Enum.Operation.Call
        );

        // If the call fails, revert.
        if (!success) {
            revert DeputyPauseModule_ExecutionFailed(string(returnData));
        }

        // Verify that the SuperchainConfig is now paused.
        if (!SUPERCHAIN_CONFIG.paused(_identifier)) {
            revert DeputyPauseModule_SuperchainNotPaused();
        }

        // Emit that the pause was triggered.
        emit PauseTriggered(deputy, _nonce, _identifier);
    }

    /// @notice Internal function to set the deputy address.
    /// @param _deputy Deputy address.
    /// @param _deputySignature Deputy signature.
    function _setDeputy(address _deputy, bytes memory _deputySignature) internal {
        // Check that the deputy signature is valid.
        bytes32 digest = _hashTypedDataV4(keccak256(abi.encode(DEPUTY_AUTH_MESSAGE_TYPEHASH, _deputy)));
        if (ECDSA.recover(digest, _deputySignature) != _deputy) {
            revert DeputyPauseModule_InvalidDeputy();
        }

        // Set the deputy address.
        deputy = _deputy;

        // Emit the DeputySet event.
        emit DeputySet(_deputy);
    }
}

src/safe/LivenessGuard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.15;

// Safe
import { Safe } from "safe-contracts/Safe.sol";
import { BaseGuard } from "safe-contracts/base/GuardManager.sol";
import { Enum } from "safe-contracts/common/Enum.sol";

// Libraries
import { EnumerableSet } from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import { SafeSigners } from "src/safe/SafeSigners.sol";

// Interfaces
import { ISemver } from "interfaces/universal/ISemver.sol";

/// @title LivenessGuard
/// @notice This Guard contract is used to track the liveness of Safe owners.
/// @dev It keeps track of the last time each owner participated in signing a transaction.
///      If an owner does not participate in a transaction for a certain period of time, they are considered inactive.
///      This Guard is intended to be used in conjunction with the LivenessModule contract, but does
///      not depend on it.
///      Note: Both `checkTransaction` and `checkAfterExecution` are called once each by the Safe contract
///      before and after the execution of a transaction. It is critical that neither function revert,
///      otherwise the Safe contract will be unable to execute a transaction.
contract LivenessGuard is ISemver, BaseGuard {
    using EnumerableSet for EnumerableSet.AddressSet;

    /// @notice Emitted when an owner is recorded.
    /// @param owner The owner's address.
    event OwnerRecorded(address owner);

    /// @notice Semantic version.
    /// @custom:semver 1.1.0
    string public constant version = "1.1.0";

    /// @notice The safe account for which this contract will be the guard.
    Safe internal immutable SAFE;

    /// @notice A mapping of the timestamp at which an owner last participated in signing a
    ///         an executed transaction, or called showLiveness.
    mapping(address => uint256) public lastLive;

    /// @notice An enumerable set of addresses used to store the list of owners before execution,
    ///         and then to update the lastLive mapping according to changes in the set observed
    ///         after execution.
    EnumerableSet.AddressSet internal ownersBefore;

    /// @notice Constructor.
    /// @param _safe The safe account for which this contract will be the guard.
    constructor(Safe _safe) {
        SAFE = _safe;
        address[] memory owners = _safe.getOwners();
        for (uint256 i = 0; i < owners.length; i++) {
            address owner = owners[i];
            lastLive[owner] = block.timestamp;
            emit OwnerRecorded(owner);
        }
    }

    /// @notice Getter function for the Safe contract instance
    /// @return safe_ The Safe contract instance
    function safe() public view returns (Safe safe_) {
        safe_ = SAFE;
    }

    /// @notice Internal function to ensure that only the Safe can call certain functions.
    function _requireOnlySafe() internal view {
        require(msg.sender == address(SAFE), "LivenessGuard: only Safe can call this function");
    }

    /// @notice Records the most recent time which any owner has signed a transaction.
    /// @dev Called by the Safe contract before execution of a transaction.
    function checkTransaction(
        address _to,
        uint256 _value,
        bytes memory _data,
        Enum.Operation _operation,
        uint256 _safeTxGas,
        uint256 _baseGas,
        uint256 _gasPrice,
        address _gasToken,
        address payable _refundReceiver,
        bytes memory _signatures,
        address _msgSender
    )
        external
    {
        _msgSender; // silence unused variable warning
        _requireOnlySafe();

        // Cache the set of owners prior to execution.
        // This will be used in the checkAfterExecution method.
        address[] memory owners = SAFE.getOwners();
        for (uint256 i = 0; i < owners.length; i++) {
            ownersBefore.add(owners[i]);
        }

        // This call will reenter to the Safe which is calling it. This is OK because it is only reading the
        // nonce, and using the getTransactionHash() method.
        bytes32 txHash = SAFE.getTransactionHash({
            to: _to,
            value: _value,
            data: _data,
            operation: _operation,
            safeTxGas: _safeTxGas,
            baseGas: _baseGas,
            gasPrice: _gasPrice,
            gasToken: _gasToken,
            refundReceiver: _refundReceiver,
            _nonce: SAFE.nonce() - 1
        });

        uint256 threshold = SAFE.getThreshold();
        address[] memory signers =
            SafeSigners.getNSigners({ _dataHash: txHash, _signatures: _signatures, _requiredSignatures: threshold });

        for (uint256 i = 0; i < signers.length; i++) {
            lastLive[signers[i]] = block.timestamp;
            emit OwnerRecorded(signers[i]);
        }
    }

    /// @notice Update the lastLive mapping according to the set of owners before and after execution.
    /// @dev Called by the Safe contract after the execution of a transaction.
    ///      We use this post execution hook to compare the set of owners before and after.
    ///      If the set of owners has changed then we:
    ///      1. Add new owners to the lastLive mapping
    ///      2. Delete removed owners from the lastLive mapping
    function checkAfterExecution(bytes32, bool) external {
        _requireOnlySafe();
        // Get the current set of owners
        address[] memory ownersAfter = SAFE.getOwners();

        // Iterate over the current owners, and remove one at a time from the ownersBefore set.
        for (uint256 i = 0; i < ownersAfter.length; i++) {
            // If the value was present, remove() returns true.
            address ownerAfter = ownersAfter[i];
            if (ownersBefore.remove(ownerAfter) == false) {
                // This address was not already an owner, add it to the lastLive mapping
                lastLive[ownerAfter] = block.timestamp;
            }
        }

        // Now iterate over the remaining ownersBefore entries. Any remaining addresses are no longer an owner, so we
        // delete them from the lastLive mapping.
        // We cache the ownersBefore set before iterating over it, because the remove() method mutates the set.
        address[] memory ownersBeforeCache = ownersBefore.values();
        for (uint256 i = 0; i < ownersBeforeCache.length; i++) {
            address ownerBefore = ownersBeforeCache[i];
            delete lastLive[ownerBefore];
            ownersBefore.remove(ownerBefore);
        }
    }

    /// @notice Enables an owner to demonstrate liveness by calling this method directly.
    ///         This is useful for owners who have not recently signed a transaction via the Safe.
    function showLiveness() external {
        require(SAFE.isOwner(msg.sender), "LivenessGuard: only Safe owners may demonstrate liveness");
        lastLive[msg.sender] = block.timestamp;

        emit OwnerRecorded(msg.sender);
    }
}

