            abi.encodeCall(IDisputeGameFactory.gameImpls, (GameTypes.SUPER_CANNON_KONA)),
            abi.encode(address(0xdead))
        );
        assertEq("MIG-CHAIN-1-70", _validateMigration(true));
    }
}

