        assertTrue(SemverComp.gte("1.2.4", "1.2.3"));
        assertTrue(SemverComp.gte("1.3.0", "1.2.3"));
        assertTrue(SemverComp.gte("2.0.0", "1.2.3"));

        assertFalse(SemverComp.gte("1.2.2", "1.2.3"));
        assertFalse(SemverComp.gte("1.9.9", "2.0.0"));
