        staking.stake(_stakeAmount, alice);

        uint128 remaining = _stakeAmount - _unstakeAmount;

        vm.expectEmit(address(staking));
        emit EffectiveStakeChanged(alice, remaining);
        vm.expectEmit(address(staking));
