        ctx_.output = new FetchChainInfoOutput();

        ctx_.proxyAdminOwner = TEST_PROXY_ADMIN_OWNER;
        ctx_.proxyAdmin = address(new ProxyAdminMock(ctx_.proxyAdminOwner));

        return ctx_;
